/* harmony default export */ __webpack_exports__["default"] = ({
  onLoad(e) {
    this.id = e.id || '';
  },
  onShow() {
    this.getOrderGoodsDetail();
  },
  computed: {
    header() {
      return {
        token: this.vuex_token || '',
        uid: this.vuex_user.id || 0
      };
    },
    formdata() {
      let multipart = this.vuex_config.config && this.vuex_config.config.upload.multipart || '';
      let isObj = this.$u.test.object(multipart);
      if (isObj) {
        return this.vuex_config.config.upload.multipart;
      }
      return {};
    },
    uploadurl() {
      if (!this.vuex_config.upload) {
        return '';
      }
      return this.vuex_config.upload.uploadurl;
    }
  },
  data() {
    return {
      id: '',
      info: {},
      list: [{
        name: '仅退款',
        value: 1
      }, {
        name: '退货退款',
        value: 2
      }],
      type: 2,
      loading: true,
      reason: '',
      expressno: '',
      images: ''
    };
  },
  methods: {
    getOrderGoodsDetail() {
      this.$api.orderGoodsDetail({
        id: this.id
      }).then(res => {
        if (res.code == 1) {
          this.info = res.data;
          this.loading = false;
        } else {
          this.$u.toast(res.msg);
          setTimeout(() => {
            uni.$u.route({
              type: 'back'
            });
          }, 1000);
        }
      });
    },
    onUploaded(e, name) {
      console.log(e, name);
      this.images = e.map(item => {
        return item.response.data.url;
      }).join(',');
    },
    onRemove(index, lists, name) {
      this.images = lists.map(item => {
        return item.response.data.url;
      }).join(',');
    },
    apply() {
      if (!this.reason) {
        this.$u.toast('请输入售后原因');
        return;
      }
      this.$api.ordeAfterSaleApply({
        id: this.id,
        reason: this.reason,
        images: this.images,
        expressno: this.expressno,
        type: this.type
      }).then(res => {
        this.$u.toast(res.msg);
        if (res.code) {
          setTimeout(() => {
            uni.$u.route({
              type: 'back'
            });
          }, 1500);
        }
      });
    }
  }
});

